namespace sv_0bdaf3ec1c2542338247fcb5b3722348.Services;

/// <summary>
/// Scoped service (per circuit) that holds the current warehouse selection
/// and notifies subscribers when it changes.
/// </summary>
public class WarehouseState
{
    public static readonly IReadOnlyList<WarehouseInfo> AvailableWarehouses =
    [
        new("wh-1", "Warehouse A — East"),
        new("wh-2", "Warehouse B — West"),
        new("wh-3", "Warehouse C — North"),
    ];

    private WarehouseInfo _current = AvailableWarehouses[0];

    public WarehouseInfo Current => _current;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        var match = AvailableWarehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (match is null || match == _current) return;

        _current = match;
        OnChange?.Invoke();
    }
}

namespace sv_0bdaf3ec1c2542338247fcb5b3722348.Services;

/// <summary>
/// Scoped service (per circuit) that polls for low-stock alerts and
/// broadcasts changes to all subscribed components.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private readonly Lock _lock = new();

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired from a background thread whenever new alert data arrives.
    /// Subscribers MUST wrap StateHasChanged in InvokeAsync.
    /// </summary>
    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>Simulates a database query — returns a random number 0–15.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component becomes visible and wants polling to run.
    /// Polling starts on the first subscriber and stops when all unsubscribe.
    /// </summary>
    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                _cts = new CancellationTokenSource();
                _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
                _ = PollLoopAsync(_cts.Token);
            }
        }
    }

    /// <summary>Call when a component is disposed or leaves the page.</summary>
    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount = Math.Max(0, _subscriberCount - 1);
            if (_subscriberCount == 0)
            {
                _cts?.Cancel();
                _timer?.Dispose();
                _timer = null;
                _cts?.Dispose();
                _cts = null;
            }
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on first tick
        await FetchAndNotifyAsync();

        while (_timer is not null)
        {
            try
            {
                if (!await _timer.WaitForNextTickAsync(ct))
                    break;
            }
            catch (OperationCanceledException)
            {
                break;
            }

            await FetchAndNotifyAsync();
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        var count = await GetLowStockCountAsync(_warehouseState.Current.Id);
        LowStockCount = count;
        OnAlertCountChanged?.Invoke();
    }

    private void OnWarehouseChanged()
    {
        // When the warehouse changes, immediately re-fetch if polling is active
        if (_subscriberCount > 0)
        {
            _ = FetchAndNotifyAsync();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

