@inject WarehouseState Warehouse
@implements IDisposable

<div class="warehouse-selector d-inline-flex align-items-center">
    <label class="me-2 text-nowrap fw-semibold" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            value="@Warehouse.Current.Id"
            @onchange="OnSelectionChanged">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        Warehouse.OnChange += _handler;
    }

    private void OnSelectionChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            Warehouse.SetWarehouse(id);
        }
    }

    public void Dispose() => Warehouse.OnChange -= _handler;
}

