@page "/dashboard"
@using sv_0bdaf3ec1c2542338247fcb5b3722348.Services
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard — @Warehouse.Current.Name</PageTitle>

<h1>Warehouse Dashboard</h1>
<h4 class="text-muted mb-4">@Warehouse.Current.Name</h4>

<div class="row">
    <div class="col-md-4">
        <div class="card border-warning mb-3">
            <div class="card-header">Low-Stock Alerts</div>
            <div class="card-body text-center">
                <h2>
                    @if (AlertService.LowStockCount > 0)
                    {
                        <span class="text-danger">@AlertService.LowStockCount</span>
                    }
                    else
                    {
                        <span class="text-success">0</span>
                    }
                </h2>
                <p class="card-text text-muted">
                    items below minimum level
                </p>
                <small class="text-muted">Auto-refreshes every 10 s</small>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        Warehouse.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        AlertService.StartPolling();
    }

    public void Dispose()
    {
        Warehouse.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
        AlertService.StopPolling();
    }
}

